# latin_solver.py
"""Solve the 7x7 Latin square puzzle using constraint propagation and backtracking.
The puzzle is defined in the INPUT string below. The solver fills the grid and
prints the completed square, then verifies each row and column contains numbers
1 through 7 exactly once.
"""

INPUT = """
Row 1: [1, 0, 0, 0, 5, 6, 7]
Row 2: [0, 0, 0, 0, 0, 0, 0]
Row 3: [3, 0, 0, 0, 7, 0, 2]
Row 4: [4, 0, 0, 7, 0, 0, 0]
Row 5: [5, 6, 7, 1, 0, 3, 0]
Row 6: [0, 7, 1, 2, 0, 4, 0]
Row 7: [0, 0, 0, 0, 0, 0, 6]
"""

N = 7
NUMS = set(range(1, N + 1))

def parse_input(text):
    grid = []
    for line in text.strip().splitlines():
        parts = line.split(':')[1].strip()
        row = eval(parts)
        grid.append(row)
    return grid

def print_grid(grid):
    for r in grid:
        print(' '.join(str(v) for v in r))

def is_valid(grid):
    for i in range(N):
        row_vals = [v for v in grid[i] if v != 0]
        if set(row_vals) != set(row_vals):
            return False
        col_vals = [grid[r][i] for r in range(N) if grid[r][i] != 0]
        if set(col_vals) != set(col_vals):
            return False
    return True

def row_missing(i, grid):
    return NUMS - set(grid[i])

def col_missing(j, grid):
    return NUMS - {grid[r][j] for r in range(N)}

def propagate(grid):
    changed = True
    while changed:
        changed = False
        for i in range(N):
            for j in range(N):
                if grid[i][j] == 0:
                    possible = row_missing(i, grid) & col_missing(j, grid)
                    if len(possible) == 1:
                        grid[i][j] = possible.pop()
                        changed = True
    return grid

def find_empty(grid):
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 0:
                return i, j
    return None

def backtrack(grid):
    grid = propagate(grid)
    empty = find_empty(grid)
    if not empty:
        return grid
    i, j = empty
    possible = row_missing(i, grid) & col_missing(j, grid)
    for val in possible:
        new_grid = [row[:] for row in grid]
        new_grid[i][j] = val
        result = backtrack(new_grid)
        if result:
            return result
    return None

def verify(grid):
    for i in range(N):
        if set(grid[i]) != NUMS:
            return False
    for j in range(N):
        if {grid[i][j] for i in range(N)} != NUMS:
            return False
    return True

def main():
    grid = parse_input(INPUT)
    solution = backtrack(grid)
    if solution and verify(solution):
        print("Completed Latin square:")
        print_grid(solution)
    else:
        print("No solution found.")

if __name__ == "__main__":
    main()

